// leafletIcons.js: core module for Campus Guardian frontend.
import L from 'leaflet'

// Fix para los iconos por defecto de Leaflet en producción
delete L.Icon.Default.prototype._getIconUrl

L.Icon.Default.mergeOptions({
  iconRetinaUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/images/marker-icon-2x.png',
  iconUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/images/marker-icon.png',
  shadowUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/images/marker-shadow.png',
})

// Iconos personalizados para diferentes tipos de incidencias
export const incidentIcons = {
  robo: L.icon({
    iconUrl: 'data:image/svg+xml;base64,',
    iconSize: [32, 32],
    iconAnchor: [16, 32],
    popupAnchor: [0, -32]
  }),
  vandalismo: L.icon({
    iconUrl: 'data:image/svg+xml;base64,',
    iconSize: [32, 32],
    iconAnchor: [16, 32],
    popupAnchor: [0, -32]
  }),
  accidente: L.icon({
    iconUrl: 'data:image/svg+xml;base64,',
    iconSize: [32, 32],
    iconAnchor: [16, 32],
    popupAnchor: [0, -32]
  }),
  incendio: L.icon({
    iconUrl: 'data:image/svg+xml;base64,',
    iconSize: [32, 32],
    iconAnchor: [16, 32],
    popupAnchor: [0, -32]
  }),
  situacion_incomoda: L.icon({
    iconUrl: 'data:image/svg+xml;base64,',
    iconSize: [32, 32],
    iconAnchor: [16, 32],
    popupAnchor: [0, -32]
  }),
  estafa: L.icon({
    iconUrl: 'data:image/svg+xml;base64,',
    iconSize: [32, 32],
    iconAnchor: [16, 32],
    popupAnchor: [0, -32]
  }),
  otro: L.icon({
    iconUrl: 'data:image/svg+xml;base64,',
    iconSize: [32, 32],
    iconAnchor: [16, 32],
    popupAnchor: [0, -32]
  }),
  default: L.icon({
    iconUrl: 'data:image/svg+xml;base64,',
    iconSize: [32, 32],
    iconAnchor: [16, 32],
    popupAnchor: [0, -32]
  })
}

export function getIconForIncident(tipo) {
  return incidentIcons[tipo] || incidentIcons.default
}
